/*
  this node gets called with every battery SOC change as well as on chate state change (bulk, float)
  it checks if near min or max+float and switches to idle if so
*/

// Variables
let data = context.global.data;
let batt_soc = data["batt_soc"];
let batt_mode = data["batt_mode"];
let charge_state = data["charge_state"];
let ess_setpoint = data["ess_setpoint"]

// Globals
let max_soc = context.global.max_soc;
let min_soc = context.global.min_soc;
let idle_rate = context.global.idle_rate;
let charge_rate = context.global.max_charge_setpoint;

let txt="";

// check if SOC is near min or max and adjust of so
// check if SOC is near min or max and adjust of so
if (ess_setpoint == idle_rate) {
    // in idle so nothing to do
    node.warn("Check SOC near end: already in idle")
    return;
}

if ((batt_soc > min_soc) && (batt_soc < (max_soc -1))) {
    //node.warn("Check soc near end: nowhere near end so do nothing")
    return;
}

// charging near the end
if ((ess_setpoint > idle_rate) && (batt_soc >= (max_soc - 1))) {
    if (charge_state != "Float") {
        // either in charge or bulk so continue
        node.warn("Check SOC near end: not in float")
        msg.payload = charge_rate;
        txt="Victron: Continue Charge because not in Float, at "+charge_rate;
        node.warn(txt);
        msg.domo_msg = txt;
        msg.batt_mode = context.global.data["batt_mode"]
        msg.inform_domo = true;
        return msg;
    }
    else {
        // max_soc reached and we are in float whilst charging
        node.warn("Check SOC near end: in float so idle")
        msg.payload = idle_rate;
        if (context.global.data["batt_mode"] != "IQ Smart Mode") {
            msg.batt_mode = "Idle"; // switch to idle if not in smart mode
        }
        txt="Victron: End of Charge reached, in float so switching to idle!";
        node.warn(txt);
        msg.domo_msg = txt;
        msg.inform_domo = true;
        return msg;
    }
}

// at max, still in absorption but no longer charging
if (ess_setpoint == idle_rate && charge_state != 'Float' && batt_soc == max_soc) {
    node.warn("Check SOC near end: idle but still in absorption")
    msg.payload = idle_rate;
    if (context.global.data["batt_mode"] != "IQ Smart Mode") {
        msg.batt_mode = "Idle"; // switch to idle if not in smart mode
    }
    txt="Victron: at max_soc, stay in idle!";
    node.warn(txt);
    msg.domo_msg = txt;
    msg.inform_domo = true;
    return msg;
}

// at max and in float
if (batt_soc == max_soc && charge_state == 'Float') {
    node.warn("Check SOC near end: in float so idle")
    msg.payload = idle_rate;
    if (context.global.data["batt_mode"] != "IQ Smart Mode") {
        msg.batt_mode = "Idle"; // switch to idle if not in smart mode
    }
    txt="Victron: End of Charge reached, in float so switching to idle!";
    node.warn(txt);
    msg.domo_msg = txt;
    msg.inform_domo = true;
    return msg;
}

// discharging at minimum
if ((ess_setpoint < 0) && (batt_soc <= min_soc)) {
    // at the end of discharge so switch to idle
    msg.payload = idle_rate;
    node.warn("Check SOC near end: at min soc so idle")

    if (batt_mode != "IQ Smart Mode") { 
        context.global.data["batt_mode"] = "Idle";
    }
    else {
        msg.batt_mode = context.global.data["batt_mode"];
    }
    txt="Victron: End of Discharge reached, switching to idle!";
    node.warn(txt);
    msg.domo_msg = txt;
    msg.inform_domo = true;
    return msg;
}

/*
  we should not end up here as:
    Discharging should not happen below min_soc and
    max_soc during Charge get's handled above
*/

if (batt_mode != "Idle") {
    if (((batt_soc < min_soc) && (batt_mode == "Discharge")) || ((batt_soc == max_soc) && (charge_state != "Float"))) {
        // Oops... should not be here ...
        msg.payload = idle_rate;
        context.global.data["batt_mode"] = "Idle";
        txt="Victron: Something weird happened, exception not trapped, switching to idle!";
        node.warn(txt);
        msg.batt_mode = "Idle";
        msg.domo_msg = txt;
        msg.inform_domo = true;
        return msg;
    }
}

