//
// this node adjusts the setpoint to direct solar energy into the batt instead of return to grid
//
let data = context.global.data;
let batt_mode = data["batt_mode"];
let batt_state = data["batt_state"];
let charge_state = data["charge_state"];
let smart_mode = data["smart_mode"]
let batt_soc = data["batt_soc"];
let pv_total = data["pv_total"]
let acl_total = data["acl_total"]
let new_sp = context.global.idle_rate;

let power = Math.round(data["grid_total_w"]);
let sp = Math.round(data["ess_setpoint"]);
let idle_rate = context.global.idle_rate;
let max_soc = context.global.max_soc
let txt = "";
msg.batt_mode = "Solar Balance";

//node.warn("In Solar Balance with power "+power+" and batt_mode "+batt_mode+" an smart mode "+smart_mode)
if ((batt_mode == "Solar Balance") ||
    (batt_mode == "IQ Smart Mode" && smart_mode == "solarbalance")) {
    node.warn("In solar Balance, batt_mode "+batt_mode+" with power "+power+" and setpoint "+sp)
    node.warn("In solar Balance, pv "+pv_total+" and AC load "+acl_total)
    if (pv_total < 250) {
        // no use trying to charge if there is no solar power
        return
    }
    if (power < -250) {
        // we are delivering more than 250W back to the grid so see if we can charge the batt
        node.warn("Power needs adjusting: "+power)

        if (batt_soc == max_soc && charge_state == 'Float') {
            msg.payload = idle_rate;
            txt="Victron: Solar Balance wants to charge but batt is full so Idle "+msg.payload;
            node.warn(txt);
            context.global.setpoint_adjusted = false;
        }
        else { 
            new_sp = pv_total - acl_total;
            txt="ESS Setpoint needs adjusting, power: "+power+" from: "+sp+" to "+new_sp;
            node.warn(txt)
            msg.domo_msg = txt
            msg.inform_domo = true
            msg.payload = new_sp
        }
        return msg;
    }
    else if (power > 250) {
        if (acl_total > pv_total) {
        // we are consuming more power than we have in solar energy so set setpoint to idle as there is no PV left to charge
            new_sp = idle_rate;
            txt="we are consuming more power than we have in solar energy so set setpoint to idle as there is no PV left to charge, power: "+power+" from: "+sp+" to "+new_sp;
            node.warn(txt)
            msg.domo_msg = txt
            msg.inform_domo = true
            msg.payload = new_sp
        }
        else { // power < pv_total
            new_sp = pv_total - acl_total;
            txt="Adust Setpoint as we are net consuming but there is room to charge solar energy, power: "+power+", pv: "+pv_total+" AC cons "+acl_total+ " from: "+sp+" to "+new_sp;
            node.warn(txt)
            msg.domo_msg = txt
            msg.inform_domo = true
            msg.payload = new_sp
        }
        return msg;
    }
}

