// New node: "Discharge Watchdog"
const data = context.global.data;
const idle_rate = context.global.idle_rate;
const ess_setpoint = data["ess_setpoint"] || 0;
const batt_mode = data["batt_mode"];

// Skip if a discharge setpoint is intentionally active
if (ess_setpoint < 0) return null;
// Skip if mode is Off
if (batt_mode === "Off") return null;

// bms_watt: negative = discharging (verify sign convention on your BMS)
// Alternative: use batt_discharged_w if bms_watt sign is inverted
const batt_w = data["bms_watt"] || 0;
const DISCHARGE_THRESHOLD = -500; // W — below this is real discharge, not noise

if (batt_w < DISCHARGE_THRESHOLD) {
    const txt = "Watchdog: discharge detected (" + Math.round(batt_w) + 
                "W) while setpoint is idle (" + ess_setpoint + 
                "W) in mode '" + batt_mode + "' — reissuing idle";
    node.warn(txt);
    msg.payload = idle_rate;
    msg.domo_msg = txt;
    msg.inform_domo = true;
    return msg;
}
return null;
